const bookmarks = [];
let nextId = 1;
let editingId = null;   // when set, Save updates this existing bookmark
let highlightId = null; // entry to visually flag after a render

// Two links are treated as the same page when they share host + path (+ query),
// ignoring protocol, "www.", a trailing slash, and capitalisation of the host.
function sameKey(u) {
  try {
    const x = new URL(u);
    const host = x.hostname.toLowerCase().replace(/^www\./, "");
    const path = x.pathname.replace(/\/$/, "");
    return host + path + x.search;
  } catch (e) {
    return u.trim().toLowerCase().replace(/\/$/, "");
  }
}
function findExisting(url) {
  const key = sameKey(url);
  return bookmarks.find(b => sameKey(b.url) === key) || null;
}

function render() {
  el("count").textContent = bookmarks.length + " saved";
  const list = el("list");
  if (bookmarks.length === 0) {
    list.innerHTML = '<div class="empty" id="empty">Nothing saved yet. Paste a link above to start.</div>';
    return;
  }
  list.innerHTML = bookmarks.map(b => `
    <div class="bm ${b.id === highlightId ? "highlight" : ""}" id="bm-${b.id}">
      <button class="edit-link" data-edit="${b.id}" type="button">Edit</button>
      <div class="title">${escapeHtml(b.title)}</div>
      <div class="url">${escapeHtml(b.url)}</div>
      ${b.desc ? `<div class="desc">${escapeHtml(b.desc)}</div>` : ""}
      ${b.tags.length ? `<div class="chips">${b.tags.map(t => `<span class="chip">${escapeHtml(t)}</span>`).join("")}</div>` : ""}
      ${b.note ? `<div class="note">${escapeHtml(b.note)}</div>` : ""}
    </div>
  `).join("");
  list.querySelectorAll("[data-edit]").forEach(btn =>
    btn.addEventListener("click", () => enterEditMode(Number(btn.dataset.edit), false)));
}
function escapeHtml(s) {
  return String(s).replace(/[&<>"]/g, c => ({ "&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;" }[c]));
}

function showForm(b) {
  el("url").value = b.url;
  el("title").value = b.title;
  el("desc").value = b.desc;
  el("tags").value = b.tags.join(", ");
  el("note").value = b.note;
  el("pSite").textContent = b.site || "";
  el("metaPreview").classList.add("show");
}

function enterEditMode(id, wasDuplicateAttempt) {
  const b = bookmarks.find(x => x.id === id);
  if (!b) return;
  editingId = id;
  showForm(b);
  el("formHeading").textContent = "Update this bookmark";
  el("saveBtn").textContent = "Update bookmark";
  el("modeBanner").textContent = wasDuplicateAttempt
    ? "You've already saved this link — here it is. Make your changes and press “Update bookmark”."
    : "Editing a saved bookmark. Make your changes and press “Update bookmark”.";
  el("modeBanner").classList.add("show");
  el("fetchState").className = "fetch-state";
  el("fetchState").textContent = "";
  // take the user to the existing entry
  highlightId = id;
  render();
  const node = el("bm-" + id);
  if (node) node.scrollIntoView({ behavior: "smooth", block: "center" });
  window.scrollTo({ top: 0, behavior: "smooth" });
  setTimeout(() => { highlightId = null; render(); }, 2600);
}

function resetForm() {
  editingId = null;
  el("url").value = ""; el("title").value = ""; el("desc").value = "";
  el("tags").value = ""; el("note").value = ""; el("pSite").textContent = "";
  el("metaPreview").classList.remove("show");
  el("fetchState").className = "fetch-state"; el("fetchState").textContent = "";
  el("formHeading").textContent = "Save a link";
  el("saveBtn").textContent = "Save bookmark";
  el("modeBanner").classList.remove("show"); el("modeBanner").textContent = "";
}

function save() {
  const url = el("url").value.trim();
  if (!url) return;
  const tags = el("tags").value.split(",").map(t => t.trim()).filter(Boolean);

  // Editing an existing bookmark -> update it in place.
  if (editingId !== null) {
    const b = bookmarks.find(x => x.id === editingId);
    if (b) {
      b.url = url; b.title = el("title").value.trim() || url;
      b.desc = el("desc").value.trim(); b.tags = tags; b.note = el("note").value.trim();
      b.site = el("pSite").textContent;
    }
    resetForm();
    render();
    el("saveFlash").textContent = "Updated.";
    setTimeout(() => el("saveFlash").textContent = "", 1800);
    return;
  }

  // New save -> if the link is already in the collection, go update it instead.
  const existing = findExisting(url);
  if (existing) {
    enterEditMode(existing.id, true);
    return;
  }

  bookmarks.unshift({
    id: nextId++,
    url,
    title: el("title").value.trim() || url,
    site: el("pSite").textContent,
    desc: el("desc").value.trim(),
    tags,
    note: el("note").value.trim()
  });
  resetForm();
  render();
  el("saveFlash").textContent = "Saved.";
  setTimeout(() => el("saveFlash").textContent = "", 1800);
}

el("fetchBtn").addEventListener("click", fetchDetails);
el("url").addEventListener("keydown", (e) => { if (e.key === "Enter") { e.preventDefault(); fetchDetails(); } });
el("saveBtn").addEventListener("click", save);

render();

