  el("count").textContent = q
    ? "showing " + visible.length + " of " + base.length
    : base.length + (base.length === 1 ? " bookmark" : " bookmarks");

  if (base.length === 0) {
    list.innerHTML = '<div class="empty">' + escapeHtml(emptyMessage(currentView)) + "</div>";
    return;
  }
  if (visible.length === 0) {
    list.innerHTML = '<div class="empty">No bookmarks match “' + escapeHtml(query.trim()) + '” in this view.</div>';
    return;
  }
  list.innerHTML = visible.map(b => `
    <div class="bm ${b.id === highlightId ? "highlight" : ""} ${b.readLater && !b.archived ? "is-later" : ""}" id="bm-${b.id}">
