        <button data-edit="${b.id}" type="button">Edit</button>
        ${b.archived
          ? `<button data-archive="${b.id}" type="button">Restore to All</button>`
          : `<button class="${b.readLater ? "on" : ""}" data-later="${b.id}" type="button">${b.readLater ? "Reading later ✓" : "Read later"}</button>
             <button data-archive="${b.id}" type="button">Archive</button>`}
      </div>
    </div>
  `).join("");
  list.querySelectorAll("[data-edit]").forEach(btn =>
    btn.addEventListener("click", () => enterEditMode(Number(btn.dataset.edit), false)));
  list.querySelectorAll("[data-later]").forEach(btn =>
    btn.addEventListener("click", () => toggleLater(Number(btn.dataset.later))));
  list.querySelectorAll("[data-archive]").forEach(btn =>
    btn.addEventListener("click", () => toggleArchive(Number(btn.dataset.archive))));
}

function toggleLater(id) {
  const b = bookmarks.find(x => x.id === id);
  if (b) { b.readLater = !b.readLater; render(); }
}
function toggleArchive(id) {
  const b = bookmarks.find(x => x.id === id);
