:root {
  --bg: #f6f7f9; --card: #ffffff; --ink: #1c2430; --muted: #6b7683;
  --line: #e3e7ec; --accent: #2f6fed; --accent-soft: #eaf1fe; --chip: #eef1f5;
  --danger: #c0392b; --ok: #2f8a4e;
}
* { box-sizing: border-box; }
body {
  margin: 0; background: var(--bg); color: var(--ink); line-height: 1.45;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}
.wrap { max-width: 760px; margin: 0 auto; padding: 0 16px; }
header.app { background: var(--card); border-bottom: 1px solid var(--line); padding: 16px 0; position: sticky; top: 0; z-index: 5; }
header.app h1 { margin: 0; font-size: 20px; }
header.app p { margin: 2px 0 0; color: var(--muted); font-size: 13px; }
main { padding: 20px 0 60px; }

.panel { background: var(--card); border: 1px solid var(--line); border-radius: 12px; padding: 18px; margin-bottom: 22px; }
.panel h2 { margin: 0 0 12px; font-size: 15px; }

label { display: block; font-size: 13px; color: var(--muted); margin: 12px 0 4px; }
input[type=text], input[type=url], textarea {
  width: 100%; padding: 10px 12px; border: 1px solid var(--line); border-radius: 8px;
  font-size: 14px; font-family: inherit; background: #fff; color: var(--ink);
}
textarea { resize: vertical; min-height: 60px; }
.row-url { display: flex; gap: 8px; }
.row-url input { flex: 1; }

.fetch-state { font-size: 13px; margin-top: 8px; min-height: 18px; }
.fetch-state.loading { color: var(--muted); }
.fetch-state.done { color: var(--ok); }
.fetch-state.error { color: var(--danger); }

.meta-preview { margin-top: 12px; padding: 12px; border: 1px dashed var(--line); border-radius: 8px; background: #fbfcfd; display: none; }
.meta-preview.show { display: block; }
.meta-preview .site { font-size: 12px; color: var(--muted); }

button { font: inherit; cursor: pointer; border-radius: 8px; border: 1px solid transparent; padding: 10px 16px; font-size: 14px; }
button.primary { background: var(--accent); color: #fff; }
button.ghost { background: #fff; border-color: var(--line); color: var(--ink); }
.actions { margin-top: 16px; display: flex; gap: 10px; align-items: center; }
.save-flash { color: var(--ok); font-size: 13px; }

.mode-banner { display: none; margin: 0 0 8px; padding: 10px 12px; border-radius: 8px; font-size: 13px;
  background: #fff5e6; border: 1px solid #f2d9a8; color: #7a5b16; }
.mode-banner.show { display: block; }

.list-head { display: flex; justify-content: space-between; align-items: baseline; }
.count { color: var(--muted); font-size: 13px; }

.views { display: flex; gap: 6px; margin: 8px 0 10px; flex-wrap: wrap; }
.view-btn { background: #fff; border: 1px solid var(--line); color: var(--muted); padding: 6px 12px; border-radius: 999px; font-size: 13px; }
.view-btn.active { background: var(--accent-soft); border-color: var(--accent); color: var(--accent); font-weight: 600; }
.vcount { font-size: 12px; opacity: .8; }

.search-box { margin: 4px 0 10px; }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }

.empty { color: var(--muted); font-size: 14px; padding: 24px 4px; text-align: center; }

.bm { border: 1px solid var(--line); border-radius: 10px; padding: 14px; margin-top: 12px; }
.bm.highlight { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
.bm.is-later { border-left: 3px solid var(--accent); }
.bm .title { font-size: 15px; font-weight: 600; }
.bm .title a { color: inherit; text-decoration: none; }
.bm .title a:hover { text-decoration: underline; }
.bm .flag { display: inline-block; font-size: 11px; color: var(--accent); background: var(--accent-soft);
  border-radius: 4px; padding: 1px 6px; margin-left: 6px; vertical-align: middle; font-weight: 500; }
.bm .url { font-size: 12px; color: var(--muted); word-break: break-all; margin-top: 2px; }
.bm .desc { font-size: 13px; color: #45505d; margin-top: 6px; overflow-wrap: anywhere; }
.bm .note { font-size: 13px; margin-top: 8px; padding: 8px 10px; background: #fffbe9; border-radius: 6px; overflow-wrap: anywhere; }
.chips { margin-top: 8px; display: flex; flex-wrap: wrap; gap: 6px; }
.chip { background: var(--chip); border-radius: 999px; padding: 3px 10px; font-size: 12px; color: #43506a; }

.bm-actions { margin-top: 10px; display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.bm-actions button { font-size: 12px; padding: 5px 10px; background: #fff; border: 1px solid var(--line); color: var(--ink); }
.bm-actions button.on { background: var(--accent-soft); border-color: var(--accent); color: var(--accent); }
.bm-actions button.danger-ghost { color: var(--danger); }
.bm-actions button.danger { background: var(--danger); border-color: var(--danger); color: #fff; }
.confirm-text { font-size: 12px; color: var(--danger); margin-right: 2px; }

